css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #fff; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; height: auto; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #07784c; text-decoration: none; }
.dcx a:hover{ color: #0ea86a; }
.dcx :focus-visible{ outline: 2px solid #0ea86a; outline-offset: 3px; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1180px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-hero] > *{ grid-column: auto !important; grid-row: auto !important; }
.dcx [data-two],.dcx [data-faq],.dcx [data-demo]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-row]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-script]{ display: none !important; }
.dcx [data-herostats]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-grid]{ grid-template-columns: repeat(4, minmax(0,1fr)) !important; }
.dcx [data-toolbar]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-ctaband]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-steps]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-steps] > div > span[data-arrow]{ display: none !important; }
.dcx [data-foot]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
}
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-grid]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-toolbar],.dcx [data-herostats],.dcx [data-steps],.dcx [data-foot]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 30px !important; }
.dcx [data-deco]{ display: none !important; }
.dcx [data-keys]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h2]{ font-size: 24px !important; }
}
